insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('8160907','utility','8160907','US','4/17/2012','Systems and methods for managing a virtual bank of repair facility credits are disclosed. Various operations for adding and subtracting credits from a repair facility virtual bank account are disclosed. Adjustments to credit totals can be based on repair facility performance with regard to an individual vehicle repair or a plurality of vehicle repairs.','System and method for allocating replacement vehicle rental costs using a virtual bank of repair facility credits','B2',44,'ipg120417.xml',0,'[0.023715205,-0.00721965,-0.005956518,0.06096425,0.011360764,0.07546094,0.010004019,0.012740262,0.0057035256,-0.018886726,-0.03184163,-0.019711068,0.08595746,-0.06519971,0.09841265,0.043194674,0.09643946,0.0051343786,0.012643083,-0.05032039,0.073246315,-0.03617566,-0.03545067,0.06683054,-0.04634024,-0.0343821,-0.0031280613,-0.0035166948,-0.025656268,0.019999513,0.054707307,-0.041270386,0.0641115,0.024194565,-0.007658517,-0.028315086,0.0066048442,-0.0037321805,0.048081543,-0.016293485,-0.016177729,-0.010225609,0.022633176,0.016142134,-0.010673406,0.05362644,-0.045334738,-0.031748846,0.0033673625,-0.048404884,-0.016638845,-0.021220246,0.034151822,-0.03564649,0.04412496,0.049633745,0.009797441,-0.040842343,-0.008393084,0.019405715,-0.07359987,-0.06974651,-0.01598299,-0.020353667,-0.045879867,0.076662354,0.0105679035,-0.0055258633,-0.010177786,-0.029046042,-0.044373445,-0.024792964,0.075895846,-0.06659324,-0.0356689,-0.09168231,-0.018086305,0.027006073,-0.05044733,0.008577988,-0.04288308,0.027528802,-0.072264954,0.022277428,0.022847285,-0.02083108,-0.03262189,-0.048395243,-0.039808165,-0.004755105,0.005462861,-0.050164018,0.023173645,0.0178767,0.056365255,0.051673017,0.031809393,0.085184455,-0.041442923,0.032507125,-0.051513676,-0.014998874,-0.0016482596,-0.063393936,-0.0026541147,0.014188173,0.