insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('10999876','utility','10999876','US','5/4/2021','A system and a method. The system may include a node of a network of nodes. The network may be a combined time division multiple access (TDMA) and contention access (CA) waveform network configured to utilize a combined TDMA and CA waveform. The combined TDMA and CA waveform may include a slot ring. The slot ring may include a plurality of TDMA slots and at least one CA period.','Time division multiple access (TDMA) and contention access waveform network','B1',19,'ipg210504.xml',0,'[-0.063006885,0.020430801,-0.011397984,-0.029931527,-0.0013517702,0.033645954,-0.016600182,0.0011921031,0.019185241,-0.03319336,-0.011695869,-0.020331642,0.069967814,-0.09756798,0.0519513,-0.019155083,0.025266893,-0.026547227,-0.013479177,0.0055149603,0.0365788,-0.0627187,-0.061897106,-0.00043126137,0.012572831,-0.114305705,0.015442262,-0.056485493,-0.060578264,0.063232586,0.008830995,-0.0030829376,0.006922197,-0.00509353,0.014922821,0.010767136,-0.0037447289,-0.020174362,0.033105507,-0.0480171,0.042682447,-0.02736091,-0.01889683,-0.022580236,-0.0609818,0.08410928,-0.080410086,0.010873445,0.020803027,-0.007450321,0.0012359986,0.006340973,0.015138821,0.025197024,0.011331504,0.02638427,0.0071239085,0.04713342,0.011670367,0.038916923,-0.021682406,-0.047458194,0.025524134,0.068769075,-0.03581558,0.07245721,-0.005126607,0.023082057,0.023037584,-0.021444771,0.0076348856,-0.058021057,0.08393253,-0.026293604,-0.0017217356,-0.045771834,-0.0004861081,-0.054426186,-0.06122855,0.04656108,-0.041965343,-0.032012295,-0.049445413,0.015700482,0.010372092,-0.023455253,-0.0413786,-0.053740676,-0.008212076,0.0111374,0.035847295,-0.038405143,0.015546765,-0.00042309685,0.003303085,0.049395535,-0.03909849,0.11317567,0.030148607,-0.018730875,-0.0124491155,0.011507319,0.005139384,-0.010554427,0.0122948205,-0.04371049,-0.008030