insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('8166919','utility','8166919','US','5/1/2012','A self-cleaning litter box (50) provides various advantages over the prior art. In particular, in one embodiment, the self-cleaning litter box (50) is configured to use a one piece litter cartridge (20) having a litter compartment (26) and a waste compartment 24. In another embodiment, the cartridge (20) is non-compartmentalized. In another embodiment, the system includes a rake assembly (56) configured with a drive assembly (58) that is protected from waste contamination. In accordance with the invention, the self-cleaning litter box (50) is configured to be used with all types of litter including crystal type litter.','Self-cleaning litter box','B2',17,'ipg120501.xml',0,'[0.00032540594,-0.029643929,0.008283924,-0.039259117,0.017343009,0.010927109,-0.016835421,-0.023948343,0.052628048,0.022146128,0.006365654,-0.022365863,0.02662753,-0.062714204,0.03324649,0.0007331009,-0.026714774,-0.044930626,0.04040696,-0.018175112,0.011186428,-0.059227914,-0.015715722,0.064021915,0.08468798,-0.085557364,0.0023394427,0.01990433,-0.051553927,0.005348936,0.0127701815,-0.029569665,0.024288971,0.002236322,0.034637716,-0.015239004,0.0030185357,0.050562218,0.0027847057,-0.010744904,0.064597584,-0.02722998,0.017878372,-0.021981746,-0.017730478,0.030720215,0.0064815953,0.003257241,0.061169557,-0.106983416,0.04947007,0.0233751,-0.020102033,-0.010036061,0.049690183,0.027189128,0.03555953,-0.003081646,0.0018875841,0.020938585,-0.01685679,-0.062293738,-0.029719736,0.03565673,0.006625626,0.08978585,0.05104231,-0.023226665,0.012319125,-0.002670105,0.0032980677,-0.061941348,0.03417702,-0.0353356,-0.009229445,0.018449875,0.010553319,0.05541838,0.0029555066,0.08956317,-0.053712673,-0.07737922,-0.03349987,-0.008777578,-0.03169768,-0.0263208,0.01062895,-0.06982193,0.044425085,0.043451075,0.002088682,-0.0801035,0.0