insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('8167653','utility','8167653','US','5/1/2012','A shield shell is composed of a tubular shell body made of a conductive resin and a metallic conductive body mounted in the shell body. The conductive body is capable of, in the base end part, connecting with a shielding member by being exposed on the surface of the shell body, while in the tip part, connecting with a shield case by being exposed on the surface of the shell body. The shielding member and the shield case are connected via the metallic conductive body of a low electric resistance, and thereby achieving excellent shielding performance in a low-frequency region in the shield shell.','Shield shell','B2',5,'ipg120501.xml',0,'[0.0031528547,0.059283603,-0.035010677,-0.001524875,-0.037019707,0.06790818,-0.026684912,-0.020597633,0.040167887,-0.036621727,-0.026280599,-0.019185962,0.04854309,-0.07286287,0.04152412,-0.015881049,0.009824813,-0.059487663,0.049612403,-0.009775087,-0.006411638,-0.06895209,-0.058069576,0.054058947,0.010815747,-0.11173587,0.0618671,-0.030571885,-0.03290993,0.05867624,0.0063535194,-0.0019966355,0.013460994,-0.06248967,-0.018764574,-0.048000693,0.040657792,-0.0054739825,-0.0028754848,0.023005236,0.029804377,-0.026402174,0.042568486,-0.0031903535,-0.021929426,0.0072175483,-0.008278253,0.04194583,0.03050024,-0.051630735,-0.018857697,0.023712717,-0.029521074,-0.060797766,0.020862855,-0.013407423,0.025145601,0.062419765,-0.00027942125,0.017338166,0.021018961,-0.053709652,-0.023882775,-0.023875002,-0.058813177,0.028205337,0.05152611,0.03217755,0.0034798745,0.007957997,-0.043824635,-0.017919077,-0.007189128,-0.014955671,-0.0024018665,0.05348865,-0.014625215,0.039423496,-0.0076576956,0.06694493,-0.057661384,-0.05947398,-0.047645688,0.012448586,0.038930558,-0.02815867,-0.04465438,0.021198157,0.0056013176,0.0718344,0.098418586,-0.02295015,0.014715013,-0.0152075