insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('11000112','utility','11000112','US','5/11/2021','A backpack and hood combination device for shielding a users head includes a backpack and a hood. The backpack comprises a pair of shoulder straps that is configured to position over shoulders of a user to couple the backpack to the user. An upper limit of the backpack is positioned proximate to a base of a neck of the user and a rear of the backpack substantially abuts a back of the user. The hood is coupled to and positioned in a pouch that is coupled to the upper limit proximate to the rear of the backpack. The hood is selectively extensible from the pouch through a pouch opening that is positioned in the pouch. The hood is configured to cover a head of the user to protect the head of the user from windchill and moisture.','Backpack and hood combination device','B1',19,'ipg210511.xml',0,'[-0.041122366,-0.009173242,-0.046731066,-0.009799887,0.02212384,0.03284648,0.016839106,-0.03547084,0.013262064,-0.02369245,-0.051632147,-0.028712094,0.06120404,-0.09542766,0.06834953,0.0026254593,0.077529915,-0.04872468,0.018798241,-0.023635013,0.008535286,-0.019338982,-0.035102375,-0.0019049123,0.021529038,-0.0788385,0.021267671,-0.050242472,-0.07198872,0.008348542,-0.009509671,-0.03305722,0.023646474,0.010909343,-0.01864729,-0.023897769,0.03538289,0.015932273,-0.054266393,-0.041232225,0.077710494,-0.062747166,0.036400788,-0.040312875,0.010075815,0.050178666,-0.07289683,-0.01707089,0.005807406,-0.07139374,0.006531567,0.030447971,-0.050251856,-0.003236532,-0.009081824,-0.0003024832,-0.016017238,0.055201337,0.01037598,-0.02192398,-0.008443186,-0.049299993,-0.058678415,-0.009447702,-0.033479318,0.01731179,0.035898935,0.015103095,0.042379644,-0.034443542,0.030858701,0.028695377,0.0014153374,-0.037537556,-0.01315313,0.014187699,0.020687323,-0.013006288,-0.03324654,0.038251027,-0.074252084,-0.0442