insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('7810510','utility','7810510','US','10/12/2010','Package/applicator for mascara, comprising a receptacle of axis XX and a wall, defining an inside space, the top portion of the wall being stiffened, and the bottom portion of the wall being flexible and capable of being moved from an expanded position to a squeezed position, a closure for temporarily closing said receptacle; a head, that is mounted on a stem, that is secured to the closure and that is capable of being put into contact with mascara, in the closed position, such that the volume defined by the bottom portion represents 15% to 60% of the total volume defined by the wall Alternatively, the package/applicator is such that the major fraction of the head is facing the stiffened portion, perpendicularly relative to axis XX.','Packaging and applicator assembly for mascara and its use in applying mascara','B2',13,'ipg101012.xml',0,'[-0.005611932,-0.0073444815,0.003333998,-0.022883248,0.048465535,0.048407093,0.037546203,-0.016497053,0.033157475,-0.023940777,-0.056884084,-0.031770673,0.06541231,-0.06182788,0.031230617,0.048697155,0.029565565,-0.048575357,0.044969797,-0.050004765,0.014188949,-0.04194719,-0.03182881,-0.007960963,0.043884497,-0.072351,0.011338431,-0.037631888,-0.024810342,-0.011536617,0.012848998,-0.004772965,0.06262316,0.032127563,0.012485354,-0.017312564,0.024335451,0.020030383,0.0004913066,0.015028581,0.052761372,-0.0442918,0.011248801,-0.04379474,-0.0308502,-0.0263467,0.010898245,0.00012596228,0.07370455,-0.08265774,0.013392492,0.02970184,-0.038514063,-0.049265422,0.0005542355,0.015461979,0.019181153,0.062612236,-0.035023257,0.02480306,-0.0072724507,-0.055119332,0.026760701,0.046716027,-0.019669969,0.10779012,0.019436693,0.062019557,0.01143853,-0.04248094,0.012544365,-0.023981662,0.03387356,-0.048671912,-0.03514596,0.0065926695,0.04486064,0.013836904,-0.047