insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('7810799','utility','7810799','US','10/12/2010','A moveable, collapsible engine test stand having adjustable engine supports and additional accessory supports that are all collapsible adjacent the base of the stand for convenient, compact storage. The stand may include accessories such as a radiator, fuel tank, instrument panel, battery, cooling lines, fuel lines, wiring harnesses, engine dynamometer and the like to permit prolonged operation and monitoring of an engine.','Collapsible engine test stand','B2',16,'ipg101012.xml',0,'[-0.012476306,-0.0027743091,0.025307976,0.008250582,-0.0056436546,0.0374465,0.021590928,-0.06646024,0.031449065,-0.033253945,-0.057055887,0.005135004,0.061594557,-0.05349606,0.03620029,0.023137206,0.06721192,-0.01652354,0.001983503,-0.050640263,0.017377477,-0.08652191,-0.03889344,0.040511325,0.005707352,-0.027430236,-0.016358117,-0.0057232906,-0.090545274,0.062351026,-0.0068359077,-0.038127128,0.091013946,0.0060868547,0.028833969,-0.020315535,0.00771139,0.028589334,0.004030655,-0.0107150655,0.051384997,-0.04196956,0.0186059,-0.06648032,0.010429153,0.015028776,0.01701662,-0.009183233,0.06827275,-0.018547509,0.0054919072,0.08907752,0.005002545,1.1697152e-07,0.0010780095,0.099015735,0.01845769,0.07039552,-0.07615145,0.04392841,-0.0039679646,-0.042743854,-0.007138666,0.0073223533,-0.08271883,0.053201005,0.026048325,-0.0036785624,0.029392553,-0.025434813,0.023623727,-0.04330627,0.018429615,-0.021847954,-0.015788179,0.026710177,-0.02616289,-0.013342854,-0.03825682,0.07142007,-0.013093478,-0.0154223675,-0.013948057,0.0066314666,-0.016234579,-0.04945851,-0.05422462,-0.016170481,-0.004598861,0.03467058,0.01439389,0.0037772045,-0.017127387,0.0031455033,0.053033143,-0.0016332439,0.02772516,0.09388413,-0.010211943,0.010723103,-0.01276179,0.030088997,0.04223046,-0.053360198,-0.05524839,0.0779655,-0.0023909318,-0.02