insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('7812144','utility','7812144','US','10/12/2010','An in vitro method is provided for screening human female subjects to assess their risk of developing cervical carcinoma which comprises screening the subject for expression of mRNA transcripts from the E6 and optionally the L1 gene of human papillomavirus, wherein subjects positive for expression of L1 and/or E6 mRNA are scored as being at risk of developing cervical carcinoma. Kits for carrying out such methods are also provided.','Method for detecting human papillomavirus mRNA','B2',4,'ipg101012.xml',0,'[0.025430202,-0.03718716,0.042345844,-0.0018269743,0.031618908,0.039588112,-0.038603686,0.039967537,-0.012860609,-0.014934898,0.009296017,-0.058566485,0.03880131,-0.050554037,-0.035254583,0.0011472229,0.019650854,-0.015132283,0.010981021,0.04219355,0.002860175,-0.05391903,-0.044151444,-0.02703078,-0.0030709405,-0.043472316,-0.09429593,-0.03365793,-0.017540887,0.003902097,-0.0016489278,0.003670634,0.07571032,0.036924332,0.08963394,-0.05434515,0.00751997,0.0204732,0.060468093,-0.019347673,0.065868154,-0.0480145,-0.0056588612,-0.029920926,-0.00073589996,0.017892994,-0.002824343,0.032199576,-0.012374867,-0.00990126,0.03306895,0.04051505,-0.00873248,0.007215401,-0.025061052,0.053802695,0.020363024,0.03630289,-0.06294154,0.07396028,0.023622567,-0.053205438,-0.013203183,0.0133096455,0.0042998856,0.05177874,0.054596722,0.052040864,-0.028614772,0.025099732,-0.02780848,0.03867302,-0.0039530317,-0.006510548,-0.040524922,-0.08163228,0.018138595,0.0074639586,0.0002025418,0.033870716,-0.044988107,-0.02163762,-0.06070542,0.0011930986,0.021864347,-0.046814572,-0.07127756,-0.0627828,-0.016672224,-0.00030740176,-0.0032478666,-0.011144081,-0.0023267092,0.023899697,0.049830247,0.029387604,-0.03636369,0.061796464,-0.0006575288,-0.031570558,0.06539918,0.011344498,-0.009310339,-0.093464606,1.5020738e