insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('7815588','utility','7815588','US','10/19/2010','A device and method for selectively controlling the direction of blood flow to and from the patient during hemodialysis is provided. Specifically, the device and method reverse flow between four fluid lines without changing connections between a patient and a hemodialysis machine. Advantageously, the blood is subjected to minimal stresses as it passes through the switching device.','Method and device for reversing lines in the procedure of hemodialysis','B2',28,'ipg101019.xml',0,'[0.024015943,-0.01594977,-0.0465662,-0.036979895,0.04817486,-0.007970929,0.0007959386,0.066535436,0.019043192,-0.0040763174,0.018184688,-0.032897066,0.05248553,-0.04275404,0.06929028,-0.026587086,0.07989773,-0.056464415,-0.012438092,0.012671761,-0.03831032,-0.07221646,-0.0470401,0.036899783,0.041767873,-0.081033625,-0.0110652065,-0.01789261,-0.044990107,-0.0023725883,0.0041391714,-0.066911116,0.041086286,-0.04297887,-0.00046154263,-0.03886072,0.018583525,0.034632314,0.009598289,-0.011552828,0.028311294,-0.0055293627,0.040482465,-0.041881777,-0.05252309,0.026982665,-0.038501233,0.061945997,-0.012412699,-0.026937187,-0.036253817,0.07224103,0.042787526,-0.059769113,0.008314058,0.014865167,0.0650829,0.042019345,-0.027665636,0.021024885,-0.0026423747,-0.059049863,-0.0313224,0.03173084,-0.055218317,0.10379525,0.05251592,0.009976216,0.04343016,-0.03871253,-0.034955528,-0.05312648,0.08666944,-0.0706501,-0.014286784,0.01077283,0.056528363,-0.009463198,-0.06914869,0.05852545,-0.05072692,-0.014324537,-0.06111526,-0.009405439,0.037618723,-0.020924268,-0.045884766,0.0021932153,0.022081539,-0.014964145,0.048344422,-0.058273237,0.015494722,-0.00214174,-0.0258664,0.06959206,0.00820169,0.043471575,-0.02914988,0.056779988,0.07016334,0.008982557,-0.026964098,-0.02160023,-0.017421862,0.05015849,-0.0036763656,0.026370257,0.0