insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('7818325','utility','7818325','US','10/19/2010','A flat file data organization technique is used for storing and retrieving geospatially organized data. The invention reduces transfer time by transferring a few large files in lieu of a large number of small files. It also moves the process of locating a given data file away from the file system to a proprietary code base. Additionally, the invention simplifies database management by having quadtree packets generated on demand.','Serving geospatially organized flat file data','B1',55,'ipg101019.xml',0,'[-0.063595206,0.005010351,0.048362434,-0.052554745,0.0097454935,0.034594327,-0.00031605628,0.02894155,0.040694933,0.017481444,-0.026083358,-0.034366086,0.06462203,-0.008030826,0.026492033,0.04629992,0.030676719,-0.09499267,-0.032855365,0.00063001947,0.05229435,0.017074535,-0.04482263,0.039823845,-0.0065355054,-0.075118974,-0.022734031,0.012095469,-0.019887183,0.058470003,0.013824329,0.009383679,0.08139593,0.0033089013,-0.011590925,-0.002432585,0.04131281,0.017929908,0.057324786,0.006808468,-0.0048767813,-0.026705477,-0.053925194,0.029541155,0.0073803193,0.0258887,-0.076274365,-0.015276967,0.0625335,-0.058064904,0.022541385,-0.01233483,0.005133879,0.007071098,0.07627416,-0.016119322,0.04915215,-0.025428439,0.033800673,-0.02314402,-0.029908426,-0.0330353,0.01587718,0.016189935,-0.0845281,0.06916014,0.009544836,-0.038597997,0.059186127,-0.050802942,0.00055628974,-0.0143898595,0.050476335,-0.053671923,0.00427747,-0.02898815,0.029728176,-0.017574059,0.006040697,0.058226243,-0.03028915,0.03520465,-0.032199617,0.033335377,0.097447224,0.008594386,-0.05801905,-0.039545316,-0.046237037,0.035140295,0.0073553068,0.007965134,0.042593114,0.00886938,0.029248426,0.059696563,-0.044004202,0.110596895,0.006524442,-0.0012353532,0.002306735,0.0036045122,0.020162642,-0.016577238,0.010112381,0.020627325