insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('7824100','utility','7824100','US','11/2/2010','A temperature measurement device includes a first thermocouple mounted on a tubular body that is shielded from the effects of radiation by a radiation shield, and a second, unshielded thermocouple. A difference in the measured temperatures from the first and second thermocouples is compared with calculated temperatures using an iterative process to determine a corrected temperature of the gas stream that estimates and compensates for incident radiation.','Temperature measurement device that estimates and compensates for incident radiation','B2',9,'ipg101102.xml',0,'[-0.0503387,0.024170741,0.042358983,-0.010054372,-0.04822558,0.019697178,0.04136021,-0.018277926,0.05229179,-0.02830489,-0.012507068,-0.0511646,0.04309995,-0.040390335,0.05023911,-0.01758922,0.03316596,-0.052861575,-0.0011758744,0.018800331,-0.035894737,-0.0925114,-0.003069587,0.030988304,-0.01034103,-0.046942737,0.026339153,-0.01947666,-0.006458696,0.05315641,-0.080561556,-0.048452232,0.07129885,-0.001577841,0.0141142,0.003640117,0.0460672,0.053258207,-0.0067394194,-0.02662974,0.02436407,-0.028325342,0.06374705,-0.01649486,-0.014731006,0.038972203,-0.049530394,-0.008532337,0.028220404,-0.047107205,-0.0067064045,0.026655309,0.003420929,-0.044667926,-0.010757531,0.0028901317,0.008021692,0.089375675,0.013288814,0.048875343,0.005849637,-0.033165146,0.0013960521,-0.0047939136,-0.044634927,0.035072718,0.08361063,0.04883913,0.0063918694,-0.029035661,0.01432928,0.01620655,0.0469537,-0.06430196,-0.009649244,0.00806789,0.02281166,0.015068767,-0.057961743,0.030737415,-0.026652046,-0.06977307,-0.04420063,-0.008397173,0.039336354,-0.037354995,-0.06721216,-0.011183494,-0.02681326,0.029108332,0.022978172,0.015244993,0.016780986,-0.0031722216,0.041607805,0.013214626,0.035218228,0.045382492,0.021255888,-0.0009199567,-0.024310974,0.0076