insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('7826628','utility','7826628','US','11/2/2010','Addressable amplified speakers assembly, and method for addressing the same, suitable for any permanent or temporary public address paging application. Amplified speakers assembly may incorporate VHF and UHF radios to provide wireless, one-way paging from a few feet to many miles away. These speakers can be added to any existing radio system with minimal effort or cost. The need for routing signal cable is eliminated, greatly reducing installation costs. Each speaker can be programmed for individual, group, or all-page access via DTMF or 2-Tone coding (up to 8 different addresses). The volume of each speaker can also be controlled remotely.','Addressable amplified speaker assembly and method for addressing the same','B2',16,'ipg101102.xml',0,'[-0.04585212,-0.029779505,0.032826353,-0.017399289,-0.011105219,0.039294578,0.016181013,-0.02687757,0.026958413,-0.025902353,-0.0824083,-0.020671496,0.04588401,-0.091186605,0.016089156,0.0057389718,0.037763704,-0.030756569,0.035053056,-0.04345633,-0.008679369,-0.055062037,-0.08481138,-0.016673146,0.046750948,-0.098136716,0.02555428,-0.059593793,-0.043472044,0.04246922,0.0033724697,-0.063032106,0.023151293,0.0005683106,0.0082874065,-0.021604497,0.01126966,-0.035732962,0.08823922,-0.03253732,0.008651789,-0.0094128745,0.029116282,-0.003156607,-0.0011535444,0.04843686,-0.033967186,-0.023622263,0.048451617,0.036729004,0.021321412,0.07186165,-0.03564738,-0.030065255,-0.018112276,0.014014508,-0.014416524,0.08174246,-0.0025455926,0.04957875,0.04232832,-0.05562011,-0.014421285,-0.013581346,-0.024891121,0.013929429,-0.034326658,-0.0029336545,-0.039456144,-0.045358773,-0.06531547,-0.03620976,0.07990825,-0.0120597975,-0.06527625,-0.0129942885,-0.01912596,0.03004784,-0.024953049,0.0715749,-0.07079319,-0.06655931,-0.05959944,0.006091012,0.020382497,-0.0437