insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('6850821','utility','6850821','US','2/1/2005','A control system for a wind power plant that includes a damage module and a control module. The damage module compares existing stress conditions on one or more component parts of the wind power plant to current energy generating costs. The control module alters electric power generated by the wind power plant based upon the comparison.','Control system for a wind power plant','B2',23,'ipg050201.xml',0,'[-0.010720813,0.0067504253,0.006739147,-0.0051031588,-0.0027602515,0.030032532,0.015512896,-0.02963902,-0.005737096,-0.030858383,0.013677072,-0.04163436,0.07792918,-0.078997836,0.05460796,0.012872693,0.060838882,-0.08462522,-0.036601145,-0.036682602,0.009149676,-0.076925,-0.050544832,0.05396178,-0.011646318,-0.04213169,-0.01239442,-0.024706049,-0.008686642,0.03110814,-0.042511187,-0.028261833,0.055711176,0.011742141,0.037256956,-0.021857454,0.053113222,0.029904084,0.028717112,-0.0530764,0.014236438,-0.047425892,0.020375377,-0.04367695,-0.005110948,0.01810983,-0.043093435,-0.008025203,0.039436493,-0.04235099,-0.00664155,0.017879631,0.018684153,0.059866827,0.05214554,0.039723717,0.045203544,0.02186608,-0.028260272,0.06783405,-0.04109558,0.0030342825,-0.014590968,0.0056141866,-0.038234282,0.091087185,0.011081338,0.015560186,-0.020062163,-0.014484858,-0.030280419,-0.018412013,0.031625785,-0.052706756,-0.02915596,-0.009330593,0.0006758972,-0.033548605,0.012677496,0.01755667,-0.075956695,-0.006121461,-0.071926914,-0.019893127,-0.003615449,-0.0038913486,-0.02120409,-0.052189697,-0.028746944,-0.007334405,-0.0038655119,0.036411565,0.09722586,-0.011685849,0.04865231,0.073101915,0.00013222895,0.064456955,-0.02370027,0.0185895,0.02828869,-0.002647999,0.00645924,-0.09330192,-0.056255966,0.052976336,-0.008346766,-0.039010465,-0.0018961728,-0.020192495,0.03308473,-0.0026045465,-0.06030791,0.001365