insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('9476349','utility','9476349','US','10/25/2016','A method and apparatus is provided for operating a piston driven, internal combustion engine (10) including a the piston (40) translating in a cylinder (30). The engine (10) has an intake stroke, followed by a partial exhaust stroke, followed by a compression stroke, followed by a power stroke and then an exhaust stroke, all of which are sequentially repeated. The compression stroke has a stroke length that is less than the stroke length of the power stroke.','Three and two half stroke freeboost internal combustion engine','B1',20,'ipg161025.xml',0,'[-0.019673944,0.032405328,0.02701743,-0.02389401,-0.008424674,-0.00015244434,0.03253315,0.010594031,0.043161757,-0.056770265,-0.073029324,0.019403787,0.05245932,-0.08745154,0.018115304,0.007964536,0.029097967,-0.03800342,0.002075771,0.0028963103,0.06737566,-0.0058315233,-0.04936846,0.06551513,-0.023242222,-0.03884947,-0.021670993,-0.011635288,-0.047343094,0.0803844,-0.046216127,-0.07468312,0.10832513,0.025337549,0.051730864,-0.034444667,-0.01333196,0.017493978,-0.039582267,0.0010404175,0.06067189,-0.05101322,0.013880955,-0.06272677,-0.077278964,0.0602567,-0.025024915,0.0284787,0.053842425,-0.06121061,-0.039581414,0.055989414,0.016697837,-0.025961444,0.015435114,-0.0047910563,0.043402947,0.05971446,-0.04857022,0.03004893,-0.01606769,-0.023396788,0.019377476,-0.029950662,-0.038702305,0.07459628,0.06443396,0.0020188782,0.012396948,0.023353972,-0.0008320561,0.013225762,0.06654,0.00038706436,-0.007420818,-0.030413905,-0.008003669,0.027283475,-0.030701216,0.06857898,-0.024294965,-0.021854818,-0.08125179,-0.02426453,0.053079817,-0.0023392846,-0.04604425,-0.0241368,0.041300073,-0.023306265,0.022163784,0.003031597,0.0012457635,-0.017922416,-0.017168347,0.027253626,0.04523556,0.1068826,0.01821648,-0.04241917,0.033530325,0.021784486,-0.026302576