insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('9485657','utility','9485657','US','11/1/2016','An electronic apparatus and a control method thereof are disclosed. The electronic apparatus according includes: a first communicator configured to communicate with an authentication terminal device; a second communicator configured to communicate with a new terminal device that is not registered with an access point (AP); a storage configured to store authentication information for accessing the AP; and a controller configured to control the second communicator to transmit the authentication information that is stored in the storage to the new terminal device in response to receiving terminal information of the new terminal device from the authentication terminal device through the first communicator.','Electronic apparatus and control method thereof','B2',20,'ipg161101.xml',0,'[-0.05019447,-0.008803452,0.019011434,-0.0010834888,0.01229763,-0.014312507,0.036935315,-0.024762847,-0.0003182133,-0.050262533,-0.012862354,-0.05184196,0.039748166,-0.09413941,0.06997101,-0.009858244,0.025513327,-0.040307757,0.01768906,-0.047760785,0.016215913,-0.040907618,-0.016422482,0.026143752,0.0006012045,-0.09949144,0.025964258,-0.04766672,-0.07388775,0.031457376,0.017244847,0.014470059,0.04281826,0.016146215,0.026000507,-0.041131414,0.043555733,-0.05442566,0.03717578,-0.038262565,0.010887101,0.015277002,0.04575605,-0.07691523,0.018902594,-0.03247693,-0.07292836,-0.063256264,-0.015005744,-0.02742002,0.0009774317,0.07265735,0.014733396,-0.051415525,-0.023282325,0.03593159,-0.016989753,0.054458912,0.009744674,0.07156038,-0.024241982,-0.05311469,-0.027312323,-0.007661303,-0.056382485,0.04987939,0.03669078,-0.0007946365,0.017874328,-0.062339514,0.0055589294,-0.06119594,0.09012818,-0.050452348,-0.059154943,-0.027823359,0.008998968,-0.0056956755,-0.046953473,0.06855648,-0.039084684,-0.026976364,-0.0956219