insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('6839148','utility','6839148','US','1/4/2005','An image input apparatus includes a reading unit for reading a manuscript image, and a communication unit for transferring the image data, which is read by the reading unit, and control data to another apparatus. The communication unit has a first mode in which a periodic data transfer can be assured, and a second mode in which the periodic data transfer cannot be assured. The communication unit transfers the image data in the first mode, and the control data in the second mode.','Image input apparatus','B1',8,'ipg050104.xml',0,'[-0.012669339,-0.0045705186,0.03238425,0.0073141186,0.0016236689,0.017534208,0.039021473,-0.029602852,0.034304176,0.0056717945,-0.0259647,-0.013484202,0.033328243,-0.09979515,0.0116772875,0.009555585,0.020682352,-0.07651979,-0.02504781,-0.046160933,0.015019202,-0.053774375,-0.023061411,-0.029185912,0.040962495,-0.09025286,-0.046432942,-0.037097488,-0.073940985,0.0413324,-0.0067459615,-0.06961828,0.06472351,0.06784909,-0.0044488753,-0.036077067,0.038086675,-0.03031254,0.005238628,0.044610944,0.03437323,0.009449872,0.050733477,-0.042965587,-0.016130162,0.04073629,-0.032283638,0.020006249,0.06398845,-0.039499436,-0.024458118,0.023326732,0.0050952774,-0.010851539,0.043487832,0.0036038833,0.067174345,0.06312418,0.01837873,0.041451678,-0.035810515,-0.040561095,0.092071764,0.034070607,-0.035128817,0.07999965,-0.0111535285,-0.070777684,-0.021130532,-0.07095048,0.021480681,-0.033878002,0.007903741,-0.06363128,0.0025277333,-0.053000018,0.045415588,-0.047289144,-0.09074653,0.015116701,-0.06077667,-0.041663602,-0.061265215,0.0016077127,0.045848608,-0.039578713,-0.027271265,-0.007113907,0.018345559,0.008782996,0.036422823,0.026084315,0.016675489,-0.010618319,0.019857585,0.033057693,-0.037052013,0.13288222,0.014172978,0.005228905,-0.0047003273,0.043853536,-0.02833089,-0.