insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('5048779','utility','5048779','US','9/17/1991','A display stand for flags or banners adapted to be supported by the weight of a vehicle. The stand comprises a tubular piece of metal having a U-shaped configuration at one end including an arcuate portion and a pair of spaced legs extending in a common direction therefrom which form a base for receiving a vehicles tire rolled thereupon to stabilize the stand. One of the legs extends beyond the length of the other leg away from the associated vehicle and includes an outer end deflected upwardly from the base having an inner diameter adapted to releasably receive one end of a flag pole to which the flag or banner to be displayed is attached.','Automobile weighted banner display stand','A',5,'pftaps19910917_wk38.zip',0,'[0.004163068,-0.0036701402,0.03772998,-0.011939426,-0.015076191,0.03163649,0.0280488,-0.011154304,0.02031427,-0.033962477,-0.039684646,-0.012616539,0.07050959,0.0090213325,0.043912794,0.017365389,0.078412324,0.0014580066,-0.006023974,-0.044105258,0.0043981816,-0.079828605,0.0002336563,-0.0032289037,0.070173055,-0.057354063,-0.0013607795,-0.021133786,-0.0455529,0.029402748,-0.01506161,-0.06356683,0.03195142,0.013059243,0.014950366,-0.034294724,-0.005361279,0.005748318,0.00089638506,0.0460816,0.07492523,-0.061341085,-0.038509887,-0.038482506,-0.035626315,0.051981036,-0.012565843,0.023344385,0.007397677,-0.02444305,0.05661549,0.10713919,-0.020970559,-0.04468071,0.017132564,0.06489154,0.02994233,0.06627459,-0.0544782,-0.008510086,0.0065556006,-0.049042303,0.007106362,0.0038169608,-0.059708,0.019653507,-0.024261719,-0.042889602,0.02583992,-0.026411572,0.013943989,-0.0653975,0.019492984,-0.044716146,-0.0016761536,-0.027129095,0.024032123,-0.017662019,-0.03800113,0.05882238,0.008588726,-0.0132795395,0.014036118,-0.015444108,0.003974076,-0.058882903,0.013161259,-0.037129268,