insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('10655616','utility','10655616','US','5/19/2020','A plunger tool and method relating thereto is designed to remove and insert plungers of a reciprocating pump such as during maintenance and other disassembly operations. The tool has a guide which receives and supports the plunger after removal from, and before reinsertion into, the pump. The tool also has a rack and pinion actuator for moving the plunger.','Plunger tool for reciprocation pump','B1',4,'ipg200519.xml',0,'[-0.028192883,-0.0015483508,-0.007872141,-0.06117074,0.00037215604,0.069113754,0.023933707,-0.045795124,0.016377917,0.017340336,-0.08219099,-0.00026663332,0.0051035527,-0.049291108,0.05673714,-0.000793616,0.081038095,-0.05566357,-0.010102847,-0.023466686,0.046823896,0.014228475,-0.019200273,0.028564017,0.008562036,-0.06731369,-0.0018057914,0.0131662395,-0.05148931,0.039388392,0.016153248,-0.059667736,0.10937297,0.018863186,0.032961372,0.0075286455,0.00065801636,-0.011864227,0.0066763,-0.011483435,0.017432231,-0.04503405,0.036148623,-0.057906903,0.012686462,0.067478925,-0.045196414,0.058146384,0.04639492,-0.062917694,0.03228763,0.058815263,0.012406504,-0.041754115,-0.0025581704,0.023660183,0.010617992,0.040459663,-0.044271946,0.028638976,-0.013004049,-0.045820355,-0.029210515,0.022465298,-0.098426364,0.08919018,0.014487864,0.041997466,0.009081097,-0.017400142,0.016618084,-0.022605339,0.03293089,-0.016820684,0.008090334,-0.020988505,0.007502809,0.024814278,-0.043295465,0.05396464,-0.032349955,-0.056201484,-0.035833437,-0.013221013,0.037604496,-0.060310155,-0.0015528938,-0.037189454,0.016302373,-0.010387292,-0.019875882,-0.006537415,0.0141428355,-0.017501721,0.039198916,0.060913064,0.0409629,0.047681242,0.00892125,0.043635894,0.06690906,0.027438112,0.027716763,-0.01083232,0.009822535,0.0451622,-0.01501115,-0.02795341,0.048540615,-0.048978336,0.0074649015,0.000161737