insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('8470409','utility','8470409','US','6/25/2013','A method of forming a nanowire structure is disclosed. The method comprises applying on a surface of carrier liquid a layer of a liquid composition which comprises a surfactant and a plurality of nanostructures each having a core and a shell, and heating at least one of the carrier liquid and the liquid composition to a temperature selected such that the nanostructures are segregated from the surfactant and assemble into a nanowire structure on the surface.','Nanowires, method of fabrication the same and uses thereof','B2',20,'ipg130625.xml',0,'[-0.03427287,0.02257349,0.012248932,-0.026472643,0.00072793313,0.06506424,-0.029169008,0.06301887,0.06314642,0.0027418975,0.020483391,-0.028106257,0.050484825,-0.06518142,0.062499426,0.022753742,0.08139655,-0.057946496,0.0172683,0.0072509367,0.0014417224,-0.06165566,-0.008637013,0.023790918,0.025276467,-0.037915286,-0.041552227,-0.03063784,-0.039899986,0.018611822,-0.0058707613,0.01328011,0.011435143,-0.025174817,0.037749805,-0.033994295,0.017773451,-0.021657975,0.008624199,0.013784393,0.04502354,-0.03270063,0.039699167,-0.054843113,-0.009770557,0.019074572,-0.065876536,0.035994086,0.011951127,-0.042963166,0.009987041,0.041565374,-0.020398622,-0.05819577,0.053146306,0.019231332,0.043498524,0.09215033,-0.016228387,0.0080214245,0.008884062,-0.0571681,0.02065664,-0.016473286,-0.07172904,0.035145946,0.01722049,0.04571089,-0.0076869656,-0.029877273,-0.059743017,-0.052169837,0.046395376,-0.051218677,0.014423876,-0.052156847,-0.02809288,0.021096574,-0.054435726,0.08336956,-0.030313993,-0.05926594,-0.011233808,0.0019405208,0.024142515,-0.038302828,0.011410086,-0.03636803,0.014871063,0.015409023,0.06264628,-0.060566086,0.098340444,-0.03305346,0.02483855,0.027776277,0.016802993,0.12622352,0.009631608,0.013428584,-0.0044156928,0.02561439,0.01365903,-0