insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('8480567','utility','8480567','US','7/9/2013','An endoscope system includes: an LVDS driver that outputs a differential signal; a differential transmission line that transmits the differential signal outputted from the LVDS driver; a pulse transformer including, in order to input the differential signal transmitted by the differential transmission line, two input terminals connected to an end of the differential transmission line; a resistor functioning as a bypass impedance element connected on an input side of the pulse transformer, to which the differential signal is inputted, in parallel to the pulse transformer and having, at a predetermined noise frequency of noise mixed in the differential transmission line, impedance smaller than circuit impedance of a circuit to which the pulse transformer, which is connected in parallel to the bypass impedance element, is connected; and a dielectric disposed between the two input terminals of the pulse transformer and between lines of the differential transmission line.','Endoscope system with differential signal transmission','B2',7,'ipg130709.xml',0,'[0.060982876,-0.008972272,0.02447791,-0.009353343,-0.014355512,0.0248435,0.028211335,-0.014517704,0.020325346,-0.07648004,0.019067142,-0.0014006926,0.033694502,-0.03998897,0.03428535,-0.03565443,-0.0057841516,-0.07012599,-0.050721444,0.01857044,-0.033555403,-0.0639365,-0.10480146,-0.0035469413,0.05066803,-0.094573505,0.03181015,-0.012710623,-0.08391919,0.044544496,0.011655741,-0.033174586,0.034531526,0.021862777,0.027058158,-0.01840419,-0.01792703,-0.041034427,-0.0069284057,-0.030128354,-0.009426974,-0.012795193,0.0293485,-0.03283553,-0.049463823,0.035859942,-0.013756676,0.0005323132,0.015184939,-0.006454655,-0.029706746,0.0056634545,0.050102707,-0.028967114,-0.061004054,0.031602494,0.061671875,0.043749932,-0.028180994,0.039925378,0.014