insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('4415506','utility','4415506','US','11/15/1983','The invention is a novel method of treating the distillation residue from the production of phosphorochloridothionates which comprises contacting the residue with a sufficient amount of a separating solution having a specific gravity of about 1.5, preferably phosphoric acid, to produce an organic layer which is easily separated from the remaining residue. The organic layer can be chlorinated to produce additional phosphorochloridothionate product.','Treating the residue from the production of phosphorochloridothionates','A',10,'pftaps19831115_wk46.zip',0,'[-0.021242594,-0.033588067,-0.007055979,-0.08026317,0.042719264,0.07959421,0.036996834,0.06361584,-0.029778548,0.0083652325,-0.02043868,-0.029763628,0.04235419,-0.024594992,0.007744313,-0.007440884,0.009598305,-0.07554874,0.04900456,0.051008027,0.0417339,-0.08128887,-0.0037353635,0.010889648,-0.016855694,-0.0745618,-0.010380346,-0.0136341285,-0.07341477,0.013359178,0.0042900657,-0.02994158,0.044778083,-0.03928415,0.030557292,0.005937915,0.06621547,-0.053419575,0.042266153,0.0070515224,0.06411162,-0.0444159,-0.0061509884,-0.10236314,0.0075127967,0.0040791444,-0.0012215254,-0.023550319,0.062381737,-0.068086796,0.0039711324,0.042528335,-0.010878147,-0.027446516,0.0042670188,0.0069499863,0.004339149,0.0343681,-0.005979667,0.0054415734,-0.047060035,-0.04543499,0.060036533,0.03265561,-0.060883183,0.079646185,0.057831798,0.007956994,0.009795692,-0.015521692,-0.024174431,-0.010144566,0.04260057,-0.08367358,0.0017224231,-0.05164796,-0.00060924253,0.08389019,0.034118295,0.06599469,-0.02503599,-0.05406449,-0.06265227,-0.0040260507,-0.024555657,-0.007954526,-0.038572554,-0.032945883,-0.04064664,0.04612799,-0.03173819,0.014476805,0.057084627,0.0031461061,-0.026148194,0.03748367,0.05720262,0.04409259,0.021471536,0.021070441,-0.0056731696,0.00