insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('8136600','utility','8136600','US','3/20/2012','A Vertical Annular Separation and Pumping System (VASPS) utilizing an isolation baffle to replace a standard pump shroud associated with an electrical submersible pump. The isolation baffle may be a one piece plate positioned so as to direct produced wellbore liquids around the electrical submersible pump motor to provide a cooling medium to prevent overheating and early failure of the electrical submersible pump.','Vertical annular separation and pumping system with integrated pump shroud and baffle','B2',23,'ipg120320.xml',0,'[-0.018764824,0.0016797906,-0.009794712,-0.008986902,0.028712811,0.05981293,0.024857976,0.042473987,0.018816514,-0.005926588,-0.030879471,-0.015364226,0.050276425,-0.07825867,0.00022107158,0.017610174,0.013543583,-0.033849444,0.034652364,-0.04826091,0.027429538,-0.057201583,-0.029577175,0.026274545,0.056731522,-0.07452598,0.013382487,-0.024928497,-0.06794787,0.016951498,0.03466096,-0.050029956,0.025862282,-0.04675761,0.01415235,-0.04140916,0.0069658537,0.03422294,0.0070941406,0.03535974,0.034424875,-0.0226508,0.04123785,-0.0697432,0.008031756,0.062196653,-0.025931302,0.051014822,0.058499157,-0.07401596,0.01839786,0.023659755,-0.0003559967,-0.018848091,-0.008208604,0.05569844,0.027436323,0.02384366,-0.061022215,-0.009279808,0.009482192,-0.0001982374,-0.04752172,-0.033171654,-0.08409367,0.042782202,0.0826699,-0.006086191,0.010625887,-0.053594075,-0.017914858,-0.020023383,0.1014909,-0.044763237,-0.015784109,-0.011312679,-0.030277785,0.048726767,-0.05202346,0.022574209,0.029353704,-0.020028094,0.00708441,0.042889614,0.029035797,-0.04105926,-0.0129330475,-0.07734428,0.024409771,-0.034776706,0.003102428,0.007188906,0.012831139,-0.0379402,0.01924419,0.047376502,0.0064443173,0.07925915,0.010890228,-0.017409341,0.04542426,0.014870207,0.038827546,-0.029139427,-0.0024