insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('10018781','utility','10018781','US','7/10/2018','An optical structure includes a substrate having a cavity on a first surface of the substrate, an optical component on the substrate, and an adhesive infiltrating into a gap between the substrate and the optical component to fix the optical component to the substrate. The optical component includes a recess on a second surface of the optical component, the second surface being opposed to the substrate, and the recess covers an opening of the cavity of the substrate.','Fluid control structure','B1',16,'ipg180710.xml',0,'[-0.037012458,-0.029443748,0.03594317,-0.009347746,-0.008969563,0.079650454,-0.04281196,-0.06140144,0.019686788,0.0029657676,-0.03911317,-0.041609228,0.028878096,-0.075676724,0.03717407,0.0040041422,0.043543793,-0.03605367,0.011142965,-0.0129208565,0.043242916,-0.034178134,-0.04723163,0.02618749,0.0650641,-0.107764885,0.02454351,-0.0023209979,-0.031490434,0.087050416,0.04541326,-0.025548073,0.02301304,0.025998924,0.013259769,-0.025205463,0.040126048,0.0029127335,0.0046268622,0.035583183,0.051255737,-0.055861235,0.05649538,-0.018622674,-0.06301259,0.024643347,-0.021324413,0.01007907,0.041913535,-0.05658683,0.02707411,0.01985776,-0.012807762,-0.07601539,0.033588108,0.08502707,0.06356338,0.047111392,0.010822741,-0.016485283,0.02375517,0.013318273,-0.01949081,0.013282632,-0.053367205,0.022870805,0.0146249905,0.018350337,-0.0060032555,-0.014620293,-0.0047359425,-0.043882366,0.04809417,-0.017454425,-0.012291252,0.0032820175,0.022814754,0.050862547,-0.05710944,0.09152138,-0.0002505507,-0.05819414,-0.012131067,-0.05091223,-0.0022623679,-0.06394972,-0.048731163,-0.016481519,0.025897726,0.07176441,0.017775806,-0.074988194,0.022025695,-0.015848262,0.044185657,0.027223546,-0.0289701,0.06302193,0.0026214488,-0.03126594,0.033374812,0.055298675,-0.025741471,-0.027509466,0.010604