insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('10974088','utility','10974088','US','4/13/2021','An aquatic exercise device and method of use are described herein. The aquatic exercise device provides for a full body, low impact, and decompressing workout that is unattainable by any existing product on the market. The aquatic exercise device features a buoy, a fastening mechanism, a user attachment mechanism, and a bridge connecting the buoy, the fastening mechanism, and the user attachment mechanism.','Aquatic exercise device for full-body workout and method of use','B2',10,'ipg210413.xml',0,'[-0.010388067,-0.021200506,0.010417526,-0.05684782,0.019364953,-0.0056443196,-0.01709983,0.00035832345,0.047548052,-0.012995178,-0.024186524,0.008754705,0.041703697,-0.03254797,0.05575822,0.034385692,0.0273668,-0.06084244,-0.008079766,-0.014586483,0.00011959847,-0.013606306,-0.042255476,0.058087066,0.019963117,-0.08569189,0.04074663,-0.07432687,-0.06154936,0.01855556,0.012743786,-0.035150606,0.055335592,-0.038457137,-0.0296986,-0.0024495847,-0.018018246,0.020421393,0.018180685,-0.006821474,0.026890066,-0.03403756,0.02809029,-0.046413645,0.013935449,0.049756378,-0.030575704,0.060986754,-0.01036834,-0.03126641,0.02530693,0.073367864,0.04762229,-0.047589764,0.06763466,0.06478145,0.0048777694,-0.030173402,-0.044839147,-0.032846432,-0.050352853,-0.04878611,0.004859641,-0.006405911,-0.035036318,0.05165619,-0.0042109527,0.05998021,0.05380431,-0.05851539,0.020012952,-0.01904759,0.014510985,-0.03388233,-0.0088391,0.010412616,-0.0059383395,0.026514368,-0.030442081,0.09258002,0.015088548,-0.047749348,-0.062466383,0.016052945,0.0017451927,-0.028372675,0.0029089644,-0.046718974,-0.008808134,0.028303122,0.032780264,-0.022966571,0.0029209594,0.0037659523,0.050279383,0.08264973,0.012536565,0.07885289,-0.048241217,0.10432399,0.029770833,0.026338644,0.030705927,-0.005236488,0.020005308,0.09192109,-0.01