insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('7834580','utility','7834580','US','11/16/2010','A solar powered apparatus that includes a battery, at least one photovoltaic cell (which may be part of a solar module comprising multiple photovoltaic cells), and a DC-capable AC appliance, such as a compact fluorescent light. The solar powered apparatus may also include a first DC to DC converter that receives a first electrical signal from the at least one photovoltaic cell and provides a charging signal to the battery, and a second DC to DC converter that receives a second electrical signal from the battery and provides a DC power signal to the DC-capable AC appliance.','Solar powered apparatus','B2',24,'ipg101116.xml',0,'[-0.025065336,-0.028356824,-0.003264093,0.00028152118,0.0051381025,0.013877069,0.039013863,-0.0016134216,0.040728036,0.028049504,-0.008595625,-0.055688176,0.004008489,-0.07246682,-0.020503145,0.033643384,0.046899527,-0.04040345,-0.0014028861,-0.03516724,-0.019423433,-0.08466284,-0.092553675,0.04266483,0.0890742,-0.117704436,-0.01619472,-0.0020968518,-0.02518955,0.05147121,0.018337779,-0.04369106,0.027572513,-0.002453302,-0.027806496,-0.014484228,0.05742409,0.033110246,-0.0041494844,-0.020408813,0.085631825,-0.037755612,0.018247182,-0.06700117,-0.0826552,0.042415366,-0.024934122,0.015131941,0.016669238,-0.014537945,0.024308797,-0.018113988,-0.028254583,-0.04415582,0.023675706,0.039264668,0.022447217,0.0641457,0.0003874814,0.010010169,0.027129347,-0.026545722,-0.010184382,0.02635189,-0.060220797,0.05397331,0.019255452,-0.012588502,-0.021595512,-0.0029201414,-0.017324366,-0.003177212,0.08918298,-0.043853726,0.03448772,0.0015688054,0.027513014,-0.03238052,-0.004731722,0.05877952,-0.0018517905,-0.03915393,-0.045795884,-0.00084326515,-0.03067695,-0.03152052,-0.05548372,-0.02211064,-0.027330285,0.014565415,0.014793519,-0.04684525,0.029459655,0.00064174394,0.0035236