insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('7835109','utility','7835109','US','11/16/2010','A tape guiding mechanism for guiding a traveling tape is provided including a guide roller for guiding the traveling tape and a regulator which rubs against at least one edge of the traveling tape in its width direction, in which the guide roller includes a circumferential surface with which the tape is in contact, a spiral groove is formed on the circumferential surface around an axis of the guide roller, and the traveling tape shifts to one side in a width direction on the circumferential surface of the guide roller.','Tape guiding mechanism, magnetic tape apparatus, and method for manufacturing magnetic tape','B2',14,'ipg101116.xml',0,'[0.014470243,0.0128647,0.024974098,-0.010496279,0.014360574,0.056860097,0.030410608,-0.03956726,0.056019932,-0.049040236,0.007080506,0.023250354,0.088817805,-0.058314394,0.042262886,-0.009391164,0.06663921,-0.062196355,-0.023279876,-0.053623505,0.037544623,-0.005688536,-0.020768603,0.051077414,0.012471607,-0.1056004,0.018967554,0.04398456,0.005155478,0.047732536,-0.04471468,-0.047381684,0.017627575,0.019028246,0.03208728,-0.019792989,0.0019333096,0.0013976402,0.010782565,0.023906695,0.049858414,-0.068668224,-0.03450354,-0.039407436,-0.06154841,0.031504862,-0.0360026,0.008325379,0.040470906,-0.06460557,-0.012208613,0.047272872,0.04474592,-0.0021013787,0.006262074,0.0453481,0.04654825,0.07073601,-0.029457217,-0.0029084221,0.025408605,0.021582328,0.0042471415,0.026510071,-0.06739236,0.041181527,0.014223956,0.02207842,0.03361938,-0.040113382,0.049918383,-0.0221564,-0.002921623,-0.06251852,0.024986275,-0.018210737,0.028146833,-0.019173332,-0.060548395,0.07829431,-0.03365366,-0.01372778,-0.05486754,-0.044522807,0.029069051,-0.04795953,0.017497307,-0.023565952,0.019940631,-0.0028355685,-0.02979641,0.023958942,0.05172184,-0.024506176,0.008916501,0.02115