insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('10000249','utility','10000249','US','6/19/2018','A bicycle pedal is provided with a pedal spindle, a pedal body, a first shear force sensor, a second shear force sensor, a first bending force sensor and a second bending force sensor. The pedal spindle includes a crank arm mounting part. The pedal body is rotatably mounted on the pedal spindle about a center spindle axis. The first and second shear force sensors are arranged relative to the pedal spindle to detect first and second shear components of a pedaling force with respect to the center spindle axis. The first bending force sensor is arranged relative to the pedal spindle to detect a first bending component of the pedaling force with respect to the center spindle axis. The second bending force sensor is arranged relative to the pedal spindle to detect a second bending component of the pedaling force with respect to the center spindle axis.','Bicycle pedal','B2',22,'ipg180619.xml',0,'[0.01880519,-0.029531512,0.020688578,-0.004798407,-0.036177665,0.07134021,-0.010178567,-0.012574343,0.061782096,-0.015918616,-0.024662727,0.017323986,0.054871723,-0.07636475,0.016858619,-0.002478478,0.012175732,-0.08992696,-0.007524825,-0.05795049,0.01774993,-0.06974606,-0.03237404,0.018146567,0.013050739,-0.068598166,0.006491346,-0.03618503,-0.0152336685,0.049255636,-0.025152948,-0.05318515,0.026003666,0.027714537,0.04110271,-0.002357851,0.0069324183,0.0369172,0.0058985623,-0.0032318835,0.029358052,-0.077572815,0.023718668,-0.042291746,-0.028438943,0.045503862,-0.024863373,0.036929883,-0.005864456,-0.03693157,0.004784923,0.030627506,0.033350658,-0.047466822,0.06282302,0.09821165,0.021421773,0.010390319,-0.026325395,0.042914703,-0.015123006,-0.027387101,-0.02891989,-0.0052776826,-0.004098295,0.046521973,0.004195786,0.008808595,0.05568075,-0.011581911,0.00067640434,-0.04177865,0.027849283,-0.0