insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('10000776','utility','10000776','US','6/19/2018','A method of enzyme conversion comprises the steps of immobilising an enzyme composition on a support material; drying the support material and enzyme composition to form a solid phase immobilised enzyme system; contacting the system with one or more reagents in the gas phase; allowing the enzyme system to convert the reagent(s) to product(s); wherein the enzyme composition may comprise a single enzyme or a first enzyme plus a second enzyme or multiple enzymes; and a co-factor which may be converted between first and second states; wherein the co-factor in the first state promotes reaction of the first enzyme; and wherein the co-factor in the second state promotes reaction of the second enzyme; or wherein the co-factor oscillates between first and second states with multiple enzymes.','Gas phase biocatalysis method and process','B2',15,'ipg180619.xml',0,'[0.011322051,0.012077552,0.018372528,-0.054859243,0.0017459105,0.042989325,-0.014275525,-0.026077144,0.0069447304,0.008901771,-0.0496623,-0.013188039,0.024647564,-0.079075016,0.058805313,0.018034214,0.035812974,-0.07056079,0.010777743,0.030273102,0.020889346,-0.043405898,-0.028038863,0.03588131,0.053965215,-0.041007157,-0.05680355,0.00865532,-0.007441658,0.04777811,0.048831858,-0.060221605,0.107023746,-0.017732961,0.024899099,-0.03391835,0.07747171,0.038332477,0.00990406,0.028110446,0.05566344,0.0017972826,0.013216106,-0.0024469225,0.019849882,0.014411871,-0.008786209,0.009998936,0.12171886,0.029613597,0.05472284,0.023130277,0.009406851,-0.018404776,0.09460797,0.07893298,0.014316374,0.041806072,0.005717256,0.018394994,0.0005805266,-0.05615763,-0.0015525584,0.013748411,0.025332645,0.037119474,0.023372043,0.013640585,-0.028263146,-0.015148344,0.030466767,-0.045508176,0.035090532,-0.0408551,-0.04154509,-0.042365424,0.0068772365,-0.0