insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('10002593','utility','10002593','US','6/19/2018','A guitar capo applicable to different kinds of guitars, having upper shell silica gel fixed onto an upper shell; lower shell silica gel fixed onto a lower shell; a groove provided at a center position of each of the upper shell silica gel and the lower shell silica gel; a raised platform positioned at a periphery of each groove; a connecting end of the upper shell sleeving a connecting end of the lower shell; the connecting ends of the upper shell and the lower shell connected and fixed via the double rivet; a spring mounted on the double rivet; an end of an arm of the lower shell connecting to the upper shell being connected with the screw. The upper shell silica gel is applicable to an acoustic guitar. The lower shell silica gel is applicable to a classical guitar.','Guitar capo applicable to different kinds of guitars','B2',8,'ipg180619.xml',0,'[-0.006057879,0.04238566,0.004391826,-0.0025441465,0.024542643,0.111583866,0.021321053,-0.03783398,0.023568342,0.008038159,-0.017638454,-0.027628673,0.062289048,-0.04587489,0.020982778,0.012987695,0.003127161,-0.067940675,0.0071105463,0.010223758,0.03439337,-0.042719733,-0.01764987,0.0228512,0.07483081,-0.15507782,-0.0069155907,0.0067024245,0.0124155935,0.059194032,0.07576311,-0.020797836,0.04626985,0.033662114,0.041832365,-0.051255062,0.049529936,0.011872793,0.026523493,0.04674055,0.024885816,-0.057071265,0.023048174,-0.0078647295,-0.019679556,0.06496003,-0.014333802,0.01565598,-0.006997516,-0.08912947,0.018083379,0.017123513,-0.0031475746,-0.04790082,0.050610468,0.017428817,0.032791447,0.034825962,0.011594832,0.035223175,0.035168648,-0.08467639,-0.032106806,-0.009026496,-0.007863521,0.05245361,0.022696534,0.056063052,0.0232421,0.038553745,0.066078946,-0.06197269,0.071506456,0.03792484,-0.0005733076,0.015207875,-0.008209555,0.01295479