insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('10018074','utility','10018074','US','7/10/2018','A turbocompound unit includes a bearing housing and a turbine shaft being rotatably supported in the bearing housing, wherein one end of the turbine shaft is provided with a turbine wheel. The turbocompound unit further includes a diffuser duct in which the turbine wheel is arranged to rotate, an exhaust collector extending from the diffuser duct to an exhaust outlet, and a sealing arrangement positioned in the vicinity of the turbine wheel for preventing oil from escaping from the bearing housing to the diffuser duct. The exhaust collector forms part of a buffer gas duct that is arranged to supply exhaust gas from the exhaust collector to the sealing arrangement for pressurizing the sealing arrangement.','Turbocompound unit','B2',17,'ipg180710.xml',0,'[-0.014661122,0.06440701,0.017814614,-0.027675778,0.049148872,0.042368192,-0.0017781799,0.016923057,0.027401946,-0.021960314,-0.05883391,0.012009554,0.066398636,-0.071156695,0.04664318,0.020814177,0.08573001,-0.03318169,-0.014847717,0.009517905,0.012513723,-0.045473345,0.0016814305,0.01635606,0.023931144,-0.09792371,-0.030004298,-0.0041699125,-0.0058429055,0.05060377,0.06427448,-0.029624535,0.08870051,0.0005158881,-0.009855805,-0.02802992,0.02674303,0.008342426,-0.016591052,0.045818582,0.060056638,-0.010933481,0.015866498,-0.011731425,-0.044276427,0.035702385,0.000501561,-0.023716234,0.07366086,-0.016296834,0.034066416,0.02370962,0.005849978,-0.05109286,0.055652883,0.019109843,0.0027786582,0.009366027,-0.027319051,0.005752013,0.005002941,-0.029667439,-0.015370376,-0.044687174,-0.06682002,0.021978011,0.04221815,0.020146633,0.060810518,-0.03402737,0.036029313,-0.023336008,0.00068359275,-0.04940923,-0.0005100504,0.03429747,0.01088807,0.00022580136,-0.020192025,0.0388104,-0.061498113,0.026637012,-0.036861278,0.01921996,0.038368866,-0.