insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('10020624','utility','10020624','US','7/10/2018','A multimedia faceplate includes a frame having a front face and a rear face and at least one connector mounting aperture therein, a non-Ethernet connector mounted in the connector mounting aperture, an Ethernet conversion unit that is electrically connected to the non-Ethernet connector and a plurality of wire connection contacts that are electrically connected to the Ethernet conversion unit. The Ethernet conversion unit is configured to draw an electrical power signal from either an AC to DC power conversion unit or from a Power-over-Ethernet power signal received from an Ethernet cable that is connected to the wire connection contacts.','Multimedia faceplates having ethernet conversion circuitry','B2',16,'ipg180710.xml',0,'[-0.056558486,-0.04037701,0.0037950452,-0.030047297,-0.013328867,0.0062458008,0.056636643,0.018466134,0.016511122,-0.016364126,-0.023316465,-0.007283888,0.04108523,-0.08793702,0.015691597,0.00052227016,0.0195088,-0.06186463,-0.01964324,-0.026345087,-0.014774732,-0.059838317,-0.07149809,-0.0062966365,0.081811875,-0.066031076,0.0026946862,-0.03697945,-0.07932928,0.057766337,0.043026045,-0.063624166,0.033576183,0.042745795,0.0071968627,-0.055006053,0.05151409,0.00081582676,0.0015418391,-0.0022434825,0.025986742,-0.005481389,-0.0033703262,-0.05901718,-0.029284827,0.0416143,-0.023855805,0.014139569,0.016530113,-0.036265653,0.006508529,0.040283777,-0.022874394,-0.03519983,0.019839894,0.015301478,0.016007839,0.040505692,-0.00049921754,0.012792245,-0.014536192,-0.059840847,-0.020317875,-0.03959719,-0.03729226,0.05166139,-0.016453864,-0.016059415,0.021694554,-0.030123485,0.01698264,-0.059654694,0.050408892,-0.0196279,0.0016539557,0.032622706,0.018917734,-0.012755825,-0.09373382,0.023613406,-0.03466778,-0.0056195953,-0.046488177,-0.025551878,-0.0033521855,-0.05599207