insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('10023343','utility','10023343','US','7/17/2018','An automatic taking-out device is configured by providing a package holding unit that holds the package; a cutting unit that cuts the two packaging sheet materials of the package in a held state in two cutting spots that are respectively present between the joining portions and the contents and that face each other with the contents therebetween; a pair of suction units that respectively suction and hold the two packaging sheet materials inside the two cutting spots; a driving unit that moves at least one of the suction units in a direction separated from the contents; and an inclining unit that inclines the two packaging sheet materials inside the two cutting spots and the contents in a state where a positional deviation in an up-down direction occurs with respect to the two cutting spots, and drops the contents out of the two packaging sheet materials.','Automatic taking-out method and device for packaged contents','B2',11,'ipg180717.xml',0,'[0.0035832433,-0.027694717,0.049250495,-0.020391364,0.058545712,0.03511678,-0.022053745,-0.005769488,0.022930728,0.0005734921,0.014115852,-0.0053466354,0.07492467,-0.04611464,0.024856212,-0.004193017,0.028111408,-0.07388867,0.01500896,-0.026184268,0.018898217,-0.041192517,0.005273813,0.016783534,0.023807777,-0.10337708,-0.03749411,-0.018766759,-0.062249225,0.08092045,-0.0103140315,-0.06901095,0.03872445,-0.03345017,0.020994239,-0.048079446,0.016376426,0.016208563,0.0149885025,0.031368367,0.07636542,-0.015213482,-0.013803292,-0.07359422,-0.056798294,0.016021142,-0.0023208156,0.0009872718,0.043046042,-0.057946533,0.007240193,0.035522807,0.014594978,-0.052598204,0.001197651,0.049305018,-0.012542039,0.07800129,-0.0095557645,0.001208558,-0.008519069,-0.021194922,0.0021812897,0.014295047,-0.06440126,0.052842103,0.013512828,-0.010306155,0.0083499