insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('10973220','utility','10973220','US','4/13/2021','A sprayer for spraying liquid onto a target area or band, the sprayer comprising a shield (10) and a nozzle arrangement for spraying liquid in a spray pattern. The shield (10) comprises a hood (12) at an upper portion of the shield (10) and a flexible skirt (14) at a lower portion of shield (10). The shield (10) surrounds the nozzle arrangement and the spray pattern allowing liquid to be sprayed onto the target area or band through an opening at the bottom of the shield (10). The skirt (14) comprises an inner membrane (40) and an outer membrane (42) which encircle the opening.','Sprayer system','B2',21,'ipg210413.xml',0,'[-0.0034053803,0.029909842,-0.03477522,-0.0159893,-0.04077531,0.01117713,0.031092037,0.011033357,0.05466866,-0.037304875,-0.022794485,-0.048572246,0.060962263,-0.07029123,0.065881155,0.014927766,0.04196311,-0.038493503,0.0843128,-0.036800012,-0.022319412,-0.05670625,-0.06726667,0.043784045,0.05821215,-0.05423251,0.04808415,-0.06703079,-0.04779836,0.01073732,0.014965889,-0.029578649,0.0365327,-0.00850053,-0.017699525,0.014356655,-0.003734874,0.03790178,0.015353955,0.0146491155,0.047114342,-0.039093494,0.028256746,-0.04485063,-0.034955945,-0.010543251,-0.031153826,0.011713971,0.035211768,-0.048165828,0.006829189,0.07856277,-0.011001046,-0.018867739,0.04062093,-0.0047778105,0.014440374,0.092563584,-0.0037248186,-0.029452452,0.0031097548,0.010070218,-0.04076625,0.039156597,-0.100938216,0.0470106,0.035464868,0.060442306,0.003349644,-0.046101123,-0.03644195,-0.031129582,0.009555563,-0.054315664,-0.019641763,-0.0068467655,-0.0073271818,0.02034115,-0.04013349,0.09352249,-0.05750177,-0.03810452,-0.0371914,0.0027714074,0.00677704,-0.043717682,-0.01077298,-0.02362372,-0.0037163354,-0.013550477,0.024101084,-0.03692381,0.049040023,-0.025585698,0.056262013,0.044862572,-0.0140