insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('10973608','utility','10973608','US','4/13/2021','Embodiments disclose a disposable protective assembly apparatus for a dental syringe body of a dental syringe. The apparatus is a combination of a disposable syringe tip and a disposable protective sleeve, the sleeve being pre-attached to the syringe tip, and the sleeve being in a pre-folded position to be quickly and easily slid over the dental syringe prior to a dental operation.','Disposable protective assembly apparatus for a dental syringe','B2',10,'ipg210413.xml',0,'[-0.0053141355,-0.013261802,-0.024959136,-0.015105786,0.010160814,0.035004146,0.007635079,-0.04397389,0.030045334,-0.02963821,-0.018291514,-0.036979407,0.04267751,-0.05737699,0.05970824,-0.032310326,0.034071792,-0.02188292,0.043222405,0.00035063736,-0.023345187,-0.032351434,-0.023212286,0.00889586,0.063224055,-0.05437721,-0.006394509,-0.057927158,-0.062634915,0.03439291,-0.012099174,-0.0015000755,0.05239776,-0.014332962,-0.022806786,-0.0440394,0.009156799,-0.048741274,0.018744646,0.040430456,0.09247852,-0.043051198,0.021269243,-0.06767946,-0.009492949,-0.010507987,0.03281547,0.06604872,0.011502758,-0.043578587,0.03261927,0.09736706,-0.012808343,-0.01574346,0.045802128,0.020956445,0.02484726,0.0659273,0.0072775213,0.008883974,0.015498886,-0.0151691,-0.046956837,0.054105684,-0.06615674,0.07359275,0.057058807,0.03681497,0.030383442,-0.01104477,0.03406263,0.0032165465,0.005752801,-0.048623353,-0.0048569967,-0.008533679,0.039059345,0.056455784,-0.033583578,0.08370452,-0.08162048,-0.010917658,-0.049095824,-0.050215423,0.022438135,-0.025401348,-0.029443111,-0.018052302,0.012167721,-0.0023666387,0.053812034,0.011458783,0.050556626,0.009548691,0.01571757,0.03221562,0.023501754,0.051988352,-0.029315252,-0.0034068322,-0.007964283,0.028370632,-0.008844851,-0.026918022,-0.022843488,0.040679373,-0.016408103,-0.036465418,0.05