insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('10975886','utility','10975886','US','4/13/2021','Provided is a turbocharger, including: a turbine impeller (impeller); nozzle vanes provided on a radially outer side of the turbine impeller; a nozzle ring to which the nozzle vanes are provided; a heat-shielding member including: an outer contact portion, which is arranged between a back surface of the turbine impeller and a wall portion of a bearing housing (housing), and is brought into contact with the nozzle ring from a side opposite to the nozzle vanes; and an inner contact portion, which is at a position on an inner side in a radial direction of the shaft with respect to the outer contact portion, and is brought into contact with a wall portion of the bearing housing from the turbine impeller side; and a separation portion, which is formed on the wall portion of the bearing housing, and is recessed toward a side of separating from the heat-shielding member with respect to a contact portion to be brought into contact with the inner contact portion of the heat-shielding member.','Turbocharger','B2',11,'ipg210413.xml',0,'[-0.03198324,0.07677705,0.016543979,-0.02092054,0.0011279241,0.055260614,-0.0068150493,-0.016353976,0.020703996,-0.041662864,-0.047252454,0.03539301,0.07353452,-0.080479294,0.025614388,0.027904123,0.08432137,-0.050476544,0.014223404,-0.019872293,0.01530951,-0.03385444,-0.0045607206,0.024566453,0.017065872,-0.09230865,-0.0050561363,0.018566765,-0.039859477,0.04026499,0.018299181,-0.025774604,0.06779452,0.0013958989,-0.012907368,-0.06874419,-0.02951764,0.030512698,0.014382302,0.032220904,0.06316719,-0.0031115965,0.014169455,-0.056642406,-0.052161586,0.027041541,-0.011805371,0.024598606,0.068636924,-0.027523845,0.019213298,0.0078120343,0.013131878,-0.06716955,-0.008779124,0.015813101,0.0035169371,0.036647465,-0.03604185,-0.0046770256,-0.014051703,-0.015797418,0