insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('10981492','utility','10981492','US','4/20/2021','An apparatus for controlling a beam pattern of a head lamp for a vehicle, comprising: an object detection unit configured to detect an object ahead of a vehicle; an ADB (Adaptive Driving Beam) head lamp configured to emit a matrix beam according to a beam pattern; a vehicle state input unit configured to receive an ADB operation state; and a control unit configured to calculate the width of a dark zone corresponding to the object and a boundary section around the dark zone according to the object detection result from the object detection unit, and then drive the ADB head lamp according to the ADB operation state.','Apparatus and method for controlling beam pattern of head lamp for vehicle','B1',14,'ipg210420.xml',0,'[0.020783857,-0.008207168,-0.0014313089,0.028766358,-0.008042288,0.057910528,0.0040007564,-0.03702391,0.06064471,-0.015768113,-0.026522832,0.023177737,0.035839017,-0.051870458,0.03313337,0.006479587,0.03557595,-0.054216348,-0.007165497,-0.11237643,-0.0054400265,-0.055702176,-0.043947205,0.016335435,0.024534326,-0.073255,0.029906817,-0.038660113,-0.034990244,0.047337525,0.06458235,-0.056649078,0.04883779,0.03584833,-0.022065252,-0.036784258,0.0060761045,0.01220055,0.007087617,0.0465754,0.060070574,-0.051642,0.0038679638,0.004484574,-0.077622496,0.0036943823,-0.01818809,0.008227485,-0.005763828,-0.03133428,-0.017373964,0.029158017,-0.010080668,-0.041651756,-0.02014937,0.025024837,0.029703092,0.033193864,-0.0016341911,-0.004141261,-0.0068270536,0.014611502,-0.0041649304,0.033434607,-0.019952722,0.014687525,0.015869701,0.03229856,0.030234745,-0.013243343,-0.0033002198,0.0034600329,0.025974117,-0.0004051115,-0.0064039216,0.004761795,0.028369602,-0.03613843,-0.03695169,0.04943955,-0.10177481,-0.053390246,-0.021386828,0.051775306,-0.02307732,-0.021234568,-0.034659695,-0.00