insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('10985530','utility','10985530','US','4/20/2021','Provided is a tunable semiconductor laser including an active gain region in which an optical signal is generated according to a modulation signal, a mode control region in which a resonant mode is controlled according to a mode control signal, and a signal chirp of the optical signal is compensated according to a first compensation signal determined based on the modulation signal, and a distributed Bragg reflector (DBR) region in which an oscillation wavelength of the optical signal is determined based on a wavelength selection signal for the optical signal, a second compensation signal for compensating for a thermal chirp of the optical signal on a basis of the modulation signal, and a heater signal provided to a heater electrode.','Tunable semiconductor laser and operation method thereof','B2',14,'ipg210420.xml',0,'[0.013289155,-0.023914801,0.035325374,-0.024134073,-0.046843316,0.050874017,-0.01992142,-0.037016377,0.09495864,-0.012367176,-0.015061348,0.026093543,0.0058558406,-0.07354735,0.01840709,-0.018126372,0.044805735,-0.051569387,0.009011202,0.0011010704,0.022505278,-0.06915146,-0.02549731,0.015119229,-0.012463463,-0.099944346,0.023712568,-0.009144826,-0.020193938,0.07954385,0.021916222,-0.051205833,0.075223856,0.027316038,0.022765212,-0.04046275,0.00225117,0.028040765,0.004273644,-0.008728844,0.04940136,-0.071441986,0.017948369,-0.025296433,-0.08009827,0.09864259,-0.02491602,0.01728442,0.0475854,-0.009689401,-0.0012201912,0.025155183,0.0023363375,-0.017129796,-0.0077053225,0.00661425,0.038604684,0.02922156,0.029009208,0.051889326,0.053268492,-0.028917408,0.02490382,0.07113593,-0.030907352,0.06009394,0.03199014,0.062363695,-0.012534477,0.0040645245,-0.041761536,0.03202134,0.028731253,-0.00018146595,-0.026807828,-0.0132192485,0.04453467,-0.021882297,-0.06196112,0.05521183