insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('9459470','utility','9459470','US','10/4/2016','Various embodiments of methods and systems for improving and enhancing vision are disclosed. Adjustable lenses or optical systems may be used to provide adaptive vision modification. In some embodiments, vision modification may be responsive to the current state of the users visual system. Certain embodiments provide correction of the subjects near and far vision. Other embodiments provide enhancement of vision beyond the physiological ranges of focal length or magnification.','Vision modification with reflected image','B2',43,'ipg161004.xml',0,'[-0.020246627,-0.013938516,0.0137113035,0.014220128,-0.053849123,0.059988003,0.011307477,-0.054215576,0.06572807,-0.03359984,-0.022903854,-0.0028503349,0.08317067,-0.08042039,0.03887493,-0.007114636,0.036500216,-0.06912736,-0.023366502,0.019503966,0.025605246,-0.05738652,-0.020567117,0.07600568,-0.0133992275,-0.07780001,-0.011360883,0.0076738885,-0.041083038,0.06750034,0.03137321,-0.05685747,0.07119113,0.047415506,0.0002105942,-0.013648826,-0.014606166,0.030075662,0.014405232,-0.02781245,0.019326344,-0.06701724,-0.020507649,-0.03087469,-0.033657335,0.07358223,-0.057224713,0.06045951,-0.015330537,0.0022178986,-0.006139651,0.045210756,0.003941753,0.008264954,0.005230423,0.04972089,0.047534812,-0.005838079,-0.0099233985,-0.0139806215,-0.037674356,-0.045614272,0.018409442,0.01605093,0.0020986153,0.07960396,-0.031522296,0.021693233,0.0074670105,0.0051295706,0.010826004,-0.041830424,0.06671929,-0.06321301,-0.025159482,-0.034917645,0.056269914,-0.003782916,-0.027548805,0.051949527,-0.06915704,-0.06721272,-0.016627684,-0.04129019,-0.008299545,-0.03699698,-0.044214554,0.0043597748,-0.008049237,0.048444137,-0.0054413835,-0.05058799,0.017374095,-0.03379492,0.033406556,0.02617987,0.034853376,0.10340324,0.03586615,0.0011284148,-0.027747748,0.0038626222