insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('6866605','utility','6866605','US','3/15/2005','A power train assembly includes an input member drivingly engaged by a power source, at least one output member and at least one gear assembly. The output member is driveably connected to the input member through the gear assembly. A brake assembly is engaged with the output member and a casing is configured to enclose the gear assembly and the brake assembly. The casing includes a main chamber in communication with at least one storage chamber and a reservoir. The storage chamber is adapted to receive a flow of lubrication fluid from the reservoir.','Power train assembly','B2',36,'ipg050315.xml',0,'[-0.010887806,0.047913507,0.03559754,0.015867906,0.0075273253,0.014849925,0.022943804,-0.0060414374,0.035472434,0.020963144,-0.06097637,0.0032689858,0.036221616,-0.08782699,0.07069154,0.012375605,0.0557743,-0.027505333,0.027055593,-0.013074728,0.007975976,-0.043371845,-0.09326498,0.0372003,0.031076204,-0.045758817,-0.0020387967,-0.005050532,-0.0124686565,0.031939268,0.035773166,-0.04801896,0.097279,-0.016866222,0.02180411,-0.030583631,0.0380783,0.015563663,-0.027513906,0.02193267,0.033423726,-0.04466261,0.04785051,-0.0036467577,-0.03824694,0.08223261,-0.017195398,-0.0021151337,0.08253771,0.001175036,0.030480366,0.027057493,0.011667061,-0.038490586,-0.0031896182,0.050677743,0.015389548,-0.006330189,-0.032088567,0.037800446,-0.02668365,-0.0663377,0.014072639,-0.008317324,-0.054227587,0.038073882,0.0339115,0.003503092,0.028959006,-0.033951327,0.0014673992,-0.04745322,0.043496035,-0.038076907,-0.03173525,0.041035846,-0.0075250585,0.01623686,-0.06713482,0.06238106,-0.03387454,-0.026964411,-0.02971779,0.0067793736,0.02528212,-0.052564356,-0.061095797,-0.030192874,0.02205415,0.035378996,0.048683316,0.005873785,0.029558236,-0.06625576,-0.008166784,0.050862294,0.021066787,0.115585946,-0.0221653