insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('11007141','utility','11007141','US','5/18/2021','An oral preparation for treating cell proliferation diseases. The oral preparation comprises hydroxylpropoxyl-����-cyclodextrin and an active component. The active component is KX2-361 or a medicinal salt thereof, and KX2-361 is represented by formula 1. By mixing hydroxylpropoxyl-ydcyclodextrin with KX2-361 or the medicinal salt thereof, an inclusion complex is formed, the solubility of the poorly-soluble drug KX2-361 is greatly improved, and accordingly the drug is prepared into an oral preparation. The oral preparation has good stability, high safety, good absorbability, high bioavailability and economical cost.','Oral preparation and preparation method thereof','B2',21,'ipg210518.xml',0,'[0.02731267,0.004032312,-0.022998543,-0.025478322,0.015923942,0.11111296,0.029656585,0.05357524,0.03792742,0.012275303,-0.020944528,0.026158087,0.053864513,-0.078431785,0.018090906,0.013561099,-0.017319638,-0.09651005,0.04404503,0.039240945,0.00033162476,-0.05322774,-0.008236829,0.013293875,0.012331279,-0.031915713,-0.05405335,0.015464944,0.0023281355,0.046681058,0.049862742,0.0033604167,0.04288737,-0.02152354,-0.0011608623,-0.060116366,0.038893227,0.025401508,0.015882324,-0.010274996,0.052660495,-0.04166775,-0.0048118336,0.029036498,-0.029848851,0.011427377,0.022802737,0.004031581,0.028250726,0.012992221,0.04810179,0.058879368,-0.017928405,0.039989535,0.03071397,0.055377997,0.041874696,0.02483041,-0.05343476,0.0644738,-0.020054534,-0.088240385,0.0067478656,-0.030292029,-0.022436678,-0.020153651,0.036100022,0.07341864,0.0376039,-0.00830259,-0.020574667,0.02403912,-0.02019325,-0.014644611,-0.0024557058,-0.026482038,0.026299749,0.05322938,0.079819396,0.044940036,-0.04797018,-0.022278188,-0.012591258,-0.019832805,-0.038028784,-0.07949311,-0.082091,-0.017414145,0.037067723,0.06739803,-0.04226575