insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('5348796','utility','5348796','US','9/20/1994','A flame-retarded textile fabric comprising (A) 85 to 15 parts by weight of a fiber comprising a polymer containing 17 to 86% by weight of a halogen, and 6 to 50% by weight of an Sb compound based on the polymer, and (B) 15 to 85 parts by weight of at least one fiber selected from the group consisting of natural fibers and chemical fibers, the total amount of the fibers (A) and (B) being 100 parts by weight. The textile fiber has not only the desired flame resistance but also excellent visual feeling, feeling of touchness, hygroscopic property, washing resistance, durability, and the like.','Flame-retarded composite fiber','A',13,'pftaps19940920_wk38.zip',0,'[-0.018409345,-0.050925072,0.03773926,-0.006517398,-0.011289866,0.031828877,0.012136516,0.011406134,0.074949674,0.0046214643,-0.015770456,-0.009654247,0.040451296,-0.07121786,0.008844182,-0.016182771,0.055918224,-0.081860006,0.010460802,-0.036301736,0.026444366,-0.06376985,-0.008127679,0.05200921,0.013743531,-0.108547896,0.0016037023,-0.02348346,-0.00044533034,0.08087697,0.0031433615,-0.053488094,0.059161097,-0.025102766,-0.006404014,-0.01025747,0.08732381,-0.019151356,0.014506023,0.027601382,0.028066976,-0.058149215,0.043211106,-0.027318211,0.015296313,0.00038808695,0.0037264244,0.050446257,0.05655112,0.013117747,0.0024103562,0.03195808,-0.054563113,0.0018736025,0.06730865,0.030856961,0.013374791,0.013019143,-0.0079370355,-0.008511432,-0.0063711694,0.014894738,-0.019188652,-0.020585258,-0.029844152,0.06756028,0.04932664,0.009519369,-0.002638361,0.01004894,-0.020133091,0.019628111,-0.016070522,-0.05572223,-0.016874515,0.009145554,-0.0041984282,0.0034410267,-0.0007689365,0.030968003,-0.09959884,-0.055782832,-0.042387072,-0.048479676,0.007831808,-0.027392812,0.023009717,-0.0024470745,-0.028165612,0.097910635,0.044298418,-0.054370