insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('5351885','utility','5351885','US','10/4/1994','A liquid jetting apparatus includes a drive mechanism, fixed, rotating and jetting cylinder sections connected in order, first rotation transmission mechanism connected to the drive mechanism and having a first operating element, second rotation transmission mechanism connected to the drive mechanism and having a second operating element, the rotational speed of the second rotation transmission mechanism being slightly different from that of the first rotation transmission mechanism, a first operating rod connected at its one end to the first rotation transmission mechanism through a position change mechanism and at its other end to the jetting cylinder section, a second operating rod connected at its one end to the second rotation transmission mechanism and at its other end to the rotating cylinder section, and a detector for detecting the positions of the first operating element and the second operating element and reversing the direction of rotation of the drive mechanism when both operating elements are present at a prescribed position.','Liquid jetting apparatus including position change and detector mechanisms','A',2,'pftaps19941004_wk40.zip',0,'[0.04453241,0.02182209,0.02901785,-0.005496785,0.006437376,0.0120908115,0.010163109,-0.010566465,0.07658368,-0.041172974,-0.08033464,0.012366494,0.040209882,-0.041880284,0.029631238,0.030619102,0.058342922,-0.07869956,-0.0015816736,-0.031216139,-0.014027029,-0.053167325,-0.04151069,0.0318367,0.037304856,-0.08720398,0.016614985,-0.010893312,-0.06446696,0.030172408,-0.0101840785,-0.025292905,0.0559504,0.037179902,0.024217755,-0.015193006,0.01666246,0.0075150332,-0.020324765,0.010918998,0.06803308,-0.042263247,0.076535895,-0.042430926,-0.09532232,0.064873256,-0.0056315786,0.02313071,0.055869095,-0.018843764,0.010200511,0.06461127,0.0410