insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('5352725','utility','5352725','US','10/4/1994','Improved methods and polymer compositions are provided whereby ultraviolet radiation degradation of substrates formed of the compositions is attenuated. In accordance with the invention, ultraviolet scattering and absorbing particles having a particle size in the range of from about 0.001 micrometer to about 0.20 micrometer in diameter are dispersed in at least a surface layer of a polymer substrate.','Attenuation of polymer substrate degradation due to ultraviolet radiation','A',8,'pftaps19941004_wk40.zip',0,'[-0.03796854,-0.007184557,0.037800103,0.012464285,-0.019531233,0.0672281,0.009321195,0.017660463,0.059734005,0.015342148,-0.011922381,-0.039560884,0.03902523,-0.06668161,0.037304785,0.013877243,0.04503565,-0.1128024,-0.022322008,0.0116677685,0.016360246,-0.059988823,0.0052528344,0.013532497,-0.004524818,-0.10744402,-0.062376734,-0.0288898,-0.03156989,0.048811562,0.03973621,-0.010221354,0.077945456,-0.010444692,0.043729525,-0.033995938,0.032544173,0.015367224,0.06976704,0.024459662,0.058601,-0.033151355,0.02108732,-0.034403216,0.0031067398,0.018437777,-0.043054495,0.037133638,0.055756107,-0.016187124,0.014183853,0.030958954,-0.03150442,-0.05058289,0.06314629,0.020439504,0.030204382,0.06800646,-0.04465627,0.014971137,0.0033175205,-0.005533943,-0.015476502,0.013792152,-0.005486699,0.050201017,0.031396452,-0.008310182,-0.038846817,-0.027509166,-0.040546726,-0.027557336,0.006515423,-0.04909856,-0.025477603,-0.060432635,0.022156442,0.0026605215,0.009058415,0.11704262,0.022267722,-0.022973299,0.010922011,-0.037963707,-0.025068723,-0.046763718,-0.020335132,0.0025855147,0.025346575,0.055392325,-0.0031052148,-0.05534627,0.060991853,0.0066806,0.011588103,0.032862037,0.013590803,0.06551623,0.05416448,-0.03167738,0.028998367,0.004516747,0.006976889,-0.006521749,-0.02135219,0.057866782,0.