insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('5353848','utility','5353848','US','10/11/1994','Uniform dispersion of mixtures of gases of different densities in gas vessels is rapidly attained by introducing the gases into the vessels in the order of their increasing densities while the vessels are in the upright position. When the quantities of the denser gases are small relative to the quantity of the least dense gas the gases are preferably metered into the vessels by pressure measurements, with the final pressures of the more dense gases being determined by differential pressure gauge measurements.','Method of filling gas cylinders','A',18,'pftaps19941011_wk41.zip',0,'[-0.062392347,0.025829826,0.015213775,0.022744397,-0.016578853,0.10469066,0.06369038,-0.014317459,0.045571525,0.0012050933,-0.10340269,-0.02594487,0.027301086,0.01968408,0.010451692,-0.038925853,0.029979855,-0.08527821,-0.04026769,-0.00023618987,-0.025150703,-0.07652765,-0.047458693,-0.016805975,-0.03518121,-0.07267231,-0.023768244,-0.08115368,-0.007738499,0.0040776297,-0.06656295,-0.03737551,0.049858253,0.007614871,0.089310706,0.0038459068,0.067525625,-0.01414605,0.024717951,-0.008717703,-0.001364699,-0.033860344,-0.005580872,0.0040585324,-0.009696179,0.031148063,-0.030010736,-0.031145506,0.031260513,-0.051147386,-0.064754,0.06125432,-0.023163686,-0.0026663912,0.053897627,-0.00986249,0.018806163,0.03076022,0.015662864,0.01683902,-0.021609886,-0.041113153,-0.0041115694,0.028026633,-0.046470728,0.028409094,0.0060601546,0.01418602,-0.007870889,-0.046203822,-0.055512857,-0.02652485,0.012720204,-0.04744681,0.036256928,-0.028009122,0.00033550794,0.030272417,-0.028683253,0.10686818,-0.050196752,-0.017450243,-0.027778424,-0.044022307,0.061233662,-0.057567123,-0.065862484,0.0005831136,-0.007687814,-0.021134095,0.03594143,0.0414916,0.014648359,-0.02708073,0.02910595,-0.017973913,-0.004399825,0.058991536,0.00208845