insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('5354635','utility','5354635','US','10/11/1994','An electrophotographic photoreceptor having a charge generation material is disclosed. The charge genaration material is mixed crystals of a titanylphthalocyanine and a vanadyl phtalocyanine, which have a characteristic peak at a Bragg angle (2.theta.) of 27.2.+-.0.2.degree. in an X-ray diffraction spectrum with a Cu-K .alpha. ray (wave length: 1.541 .ANG.) and having other specific physical property. The photoreceptor is suitably used in a printer or photocopying machine.','Electrophotographic photoreceptor comprising mixed crystals of titanylphthalocyanine and vanadylphthalocyanine','A',10,'pftaps19941011_wk41.zip',0,'[-0.023211703,-0.013674623,0.042202193,-0.04195389,0.012021373,0.04908233,0.0007113453,0.019758036,0.0050371657,-0.0017000824,-0.024920093,-0.0156141855,0.048092846,-0.049003694,-0.031670935,0.0012341406,0.06467812,-0.04586217,-0.034756776,0.023306275,0.035799254,-0.0449195,-0.020573916,0.023093695,0.022716682,-0.06391459,0.021728696,0.01636955,-0.03204139,0.09198905,0.034194566,-0.002172911,0.052124932,-0.014993618,0.033843726,-0.035284773,-0.02534801,-0.024456063,0.043183792,-0.0031380807,0.07000788,-0.054972097,-0.011296008,0.022150356,-0.046360154,0.07623638,-0.029204039,-0.03743023,-0.008929638,-0.03199511,-0.0024251323,0.10020613,0.03710887,-0.020275205,-0.002506168,0.020066185,0.07098667,0.06350919,-0.02442805,0.059941296,-0.035949796,-0.064014465,0.01746005,0.05143026,0.012079859,0.0058876947,0.02177016,0.030325143,0.009921602,-0.015537202,-0.008903144,-0.01583753,0.0032087744,-0.06084362,0.0068812887,-0.06467761,0.046938643,-0.0057265037,-0.022292865,0.09680012,-0.023145838,-0.007955622,-0.031730834,-0.00025715557,0.01856405,-0.055843882,0.025312442,0.0063251085,0.009262517,0.04636177,-0.037567876,-0.030444833,0.041040447,0.006358103,0.026986713,0.0044878