insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('5356620','utility','5356620','US','10/18/1994','In preferred embodiments this invention provides a pharmaceutical composition and a method for the treatment of allergic conjunctivitis or allergic rhinitis. The composition is an aqueous solution containing N-(3,4-dimethoxycinnamoyl)anthranilic acid or a pharmaceutically acceptable salt thereof as an active ingredient. The composition additionally contains as essential components polyvinylpyrrolidone, a basic compound and a surface active agent in prescribed quantities, and the composition has a pH of about 6.5-8.5.','Pharmaceutical compositions containing N-(3,4-dimethoxycinnamoyl) anthranilic acid','A',3,'pftaps19941018_wk42.zip',0,'[0.0021479197,-0.04787841,-0.013288347,-0.019489901,0.008310088,0.039987,0.026651002,-0.035391368,-0.039760433,-0.025881113,-0.035713054,-0.03015972,0.05647566,-0.09720436,0.010350373,0.010251176,0.03209801,-0.06209214,0.022240397,-0.0027851397,0.021889985,-0.04197952,0.013445507,0.0073314575,-0.009295957,-0.03787801,-0.0071888515,-0.033805314,-0.043816634,0.010273809,0.043050356,0.017269434,0.04695839,0.035858747,0.03135395,-0.06089963,0.043619413,-0.039046492,0.0023104406,0.009186436,0.048728436,-0.04587635,-0.034675032,-0.042385872,0.044209454,0.0049151224,0.0039853253,0.010017221,0.00661964,0.018340833,-0.017808916,0.052769497,0.0040838593,-0.011894574,0.0117173195,-0.019508502,0.00833504,0.08771453,-0.027859585,0.01718453,-0.04686774,-0.04282591,-0.012025854,0.059944738,0.056397736,0.06075403,0.063104294,-0.0045976546,0.010188179,-0.013386946,-0.040920302,-0.023116166,0.0019318218,-0.049312502,-0.028904965,-0.012074297,-0.014647631,0.056904763,0.015677948,0.059809946,-0.08963558,-0.00820804,-0.0054786094,0.015189689,-0.045476984,-0.09648548,-0.033919677,-0.025426406,0.0016064283,0.008931159,-0.0069740284,-0.013250439,0.07892106,-0.01348656,0.0